"""Manage a local namespace repository stored as JSON."""

import argparse
import json
import os
from pathlib import Path
import sys
import tempfile

from .grants import GrantError
from .metadata import RepositoryIndex
from .normalize import normalize_name
from .uploads import authorize_upload, UploadConflictError

__all__ = ['CONFLICT_EXIT', 'build_parser', 'main']

CONFLICT_EXIT = 3


def build_parser():
    """Build the command line argument parser."""
    parser = argparse.ArgumentParser(
        prog='python -m packagenamespaces',
        description='Manage repository-local package namespaces (PEP 752).',
    )
    parser.add_argument('--store', default='packagenamespaces.json',
                        help='JSON store path (default: %(default)s)')
    commands = parser.add_subparsers(dest='command', required=True)
    for command, argument, owner in (
        ('reserve', 'namespace', True),
        ('list', None, False),
        ('show', 'namespace', False),
        ('remove', 'namespace', False),
        ('register', 'project', True),
        ('grandfather', 'project', True),
        ('check-upload', 'project', True),
        ('dump', None, False),
    ):
        subparser = commands.add_parser(command)
        # Accept --store both before and after the subcommand.
        subparser.add_argument('--store', default=argparse.SUPPRESS,
                               help='JSON store path')
        if argument:
            subparser.add_argument(argument)
        if owner:
            subparser.add_argument('--owner', required=True)
        if command in ('list', 'show'):
            subparser.add_argument('--json', action='store_true')
        if command == 'dump':
            subparser.add_argument('--project')
    return parser


def _load(path):
    index = RepositoryIndex()
    try:
        with path.open(encoding='utf-8') as stream:
            data = json.load(stream)
    except FileNotFoundError:
        return index
    if (not isinstance(data, dict)
            or set(data) != {'grants', 'projects', 'grandfathered'}
            or not isinstance(data['grants'], dict)
            or not isinstance(data['projects'], dict)
            or not isinstance(data['grandfathered'], list)):
        raise ValueError('invalid store schema')
    for name, owner in data['grants'].items():
        index.store.reserve(name, owner)
    for project, owner in data['projects'].items():
        index.register_project(project, owner)
    for project in data['grandfathered']:
        index.grandfathered.add(project)
    return index


def _save(path, index):
    data = {
        'grants': {grant.name: grant.owner for grant in index.store},
        'projects': {project: index.project_owner(project)
                     for project in index.projects()},
        'grandfathered': index.grandfathered.projects(),
    }
    temporary = None
    try:
        with tempfile.NamedTemporaryFile(
            mode='w', encoding='utf-8', dir=path.parent,
            prefix=f'.{path.name}.', delete=False,
        ) as stream:
            temporary = Path(stream.name)
            json.dump(data, stream, indent=2, sort_keys=True)
            stream.write('\n')
        os.replace(temporary, path)
    finally:
        if temporary is not None:
            temporary.unlink(missing_ok=True)


def _print_json(value):
    print(json.dumps(value, sort_keys=True))


def _run(args, path, index):
    command = args.command
    if command == 'reserve':
        grant = index.store.reserve(args.namespace, args.owner)
        _save(path, index)
        print(f'reserved {grant.name} for {grant.owner}')
    elif command == 'remove':
        grant = index.store.remove(args.namespace)
        _save(path, index)
        print(f'removed {grant.name}')
    elif command in ('register', 'grandfather'):
        index.register_project(args.project, args.owner)
        project = normalize_name(args.project)
        if command == 'grandfather':
            index.grandfathered.add(project)
        _save(path, index)
        if command == 'grandfather':
            print(f'grandfathered {project}')
        else:
            print(f'registered {project} for {args.owner}')
    elif command == 'list':
        if args.json:
            _print_json([{'name': grant.name, 'owner': grant.owner}
                         for grant in index.store])
        else:
            for grant in index.store:
                print(f'{grant.name} {grant.owner}')
    elif command == 'show':
        detail = index.namespace_detail(args.namespace)
        if args.json:
            _print_json(detail)
        else:
            print(f"name: {detail['name']}")
            print(f"owner: {detail['owner']}")
            print(f"parent: {detail['parent'] or 'none'}")
            print(f"children: {', '.join(detail['children']) or 'none'}")
    elif command == 'check-upload':
        authorize_upload(args.project, args.owner, index.store,
                         index.grandfathered)
        print(f'OK {normalize_name(args.project)}')
    elif command == 'dump':
        if args.project is not None:
            _print_json(index.project_detail(args.project))
        else:
            _print_json({'api_version': index.api_version,
                         'namespaces': index.list_namespaces()})
    return 0


def main(argv=None):
    """Return 0 on success, 1 on error, or 3 on an upload conflict."""
    args = build_parser().parse_args(argv)
    try:
        path = Path(args.store)
        return _run(args, path, _load(path))
    except UploadConflictError as error:
        print(f'error: {error}', file=sys.stderr)
        return CONFLICT_EXIT
    except (GrantError, OSError, TypeError, ValueError) as error:
        print(f'error: {error}', file=sys.stderr)
        return 1
"""Installer policies requiring repository-local namespace ownership."""

from .grants import InvalidNamespaceError, _validate_name, _validate_owner
from .matching import namespace_matches
from .normalize import normalize_name

__all__ = ['SecurityPolicy']


class SecurityPolicy:
    """Allow projects owned by owner under its active policy namespaces."""

    def __init__(self, namespaces, owner):
        _validate_owner(owner)
        if isinstance(namespaces, str):
            namespaces = (namespaces,)
        try:
            namespaces = iter(namespaces)
        except TypeError:
            raise InvalidNamespaceError(
                'namespaces must be an iterable of names'
            ) from None
        self._namespaces = tuple(_validate_name(name) for name in namespaces)
        self._owner = owner

    @property
    def namespaces(self):
        return self._namespaces

    @property
    def owner(self):
        return self._owner

    def allows(self, project, index):
        """Check project ownership and an active grant on this index."""
        project = normalize_name(project)
        if (not index.supports_namespaces
                or index.project_owner(project) != self.owner):
            return False
        for namespace in self.namespaces:
            grant = index.store.get(namespace)
            if (grant is not None and grant.owner == self.owner
                    and namespace_matches(namespace, project)):
                return True
        return False

    def evaluate(self, requirements, index):
        """Return normalized project names mapped to their policy decisions."""
        return {normalize_name(project): self.allows(project, index)
                for project in requirements}
"""Upload authorization and exemptions for pre-existing projects."""

from .grants import _validate_name, _validate_owner
from .normalize import normalize_name

__all__ = [
    'CONFLICT_STATUS', 'UploadConflictError', 'GrandfatheredRegistry',
    'authorize_upload',
]

CONFLICT_STATUS = 409


class UploadConflictError(Exception):
    """An uploader does not own a matching reserved namespace."""

    status_code = CONFLICT_STATUS

    def __init__(self, project, namespace, owner):
        self.project = normalize_name(project)
        self.namespace = normalize_name(namespace)
        self.owner = owner
        super().__init__(
            f'409 Conflict: {owner!r} cannot upload {self.project!r}; '
            f'namespace {self.namespace!r} is reserved'
        )


class GrandfatheredRegistry:
    """Keep normalized project names exempt from namespace upload checks."""

    def __init__(self, projects=()):
        self._projects = set()
        for project in projects:
            self.add(project)

    def __len__(self):
        return len(self._projects)

    def __contains__(self, project):
        return (isinstance(project, str)
                and normalize_name(project) in self._projects)

    def add(self, project):
        """Exempt a project from namespace upload checks."""
        self._projects.add(_validate_name(project))

    def discard(self, project):
        """Remove an exemption, if present."""
        self._projects.discard(normalize_name(project))

    def covers(self, project):
        """Return whether the normalized project is exempt."""
        return project in self

    def projects(self):
        """Return exempt project names in sorted order."""
        return sorted(self._projects)


def authorize_upload(project, owner, store, grandfathered=None):
    """Return True when allowed, otherwise raise UploadConflictError.

    Validate the uploader before consulting grants, even for unreserved or
    grandfathered projects.  Exemptions apply to complete project names.
    """
    _validate_owner(owner)
    project = _validate_name(project)
    if grandfathered is not None and grandfathered.covers(project):
        return True
    for grant in store.matching(project):
        if grant.owner != owner:
            raise UploadConflictError(project, grant.name, owner)
    return True
